/* Rentcam — premium Portfolio + Artikel pages */
(function(){
  const e=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  function installStyle(){
    if(document.getElementById('rentcam-editorial-polish-style')) return;
    const st=document.createElement('style');
    st.id='rentcam-editorial-polish-style';
    st.textContent=`
      #app .editorial-page{padding:0 0 70px!important;background:#fff!important}
      #app .editorial-page>.container{padding-top:34px!important}
      #app .editorial-kicker{display:inline-flex!important;align-items:center!important;gap:8px!important;font-size:10px!important;font-weight:900!important;letter-spacing:.15em!important;text-transform:uppercase!important;color:#777!important;margin-bottom:14px!important}
      #app .editorial-kicker::before{content:'';width:24px;height:2px;background:#f26a21;border-radius:99px}
      #app .editorial-hero{display:grid!important;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr)!important;gap:40px!important;align-items:end!important;padding:34px 0 36px!important;border-bottom:1px solid #e9e9e9!important}
      #app .editorial-hero h1{margin:0!important;max-width:780px!important;font-size:clamp(42px,5.2vw,76px)!important;line-height:.94!important;letter-spacing:-.065em!important;color:#111!important}
      #app .editorial-hero p{margin:0!important;font-size:15px!important;line-height:1.7!important;color:#6f6f6f!important;max-width:520px!important}
      #app .editorial-stats{display:flex!important;gap:28px!important;margin-top:24px!important;flex-wrap:wrap!important}
      #app .editorial-stat b{display:block!important;font-size:20px!important;color:#111!important;letter-spacing:-.03em!important}.editorial-stat span{font-size:10px!important;color:#888!important;text-transform:uppercase!important;letter-spacing:.08em!important}

      #app .portfolio-feature{position:relative!important;margin:34px 0 22px!important;min-height:520px!important;border-radius:24px!important;overflow:hidden!important;cursor:pointer!important;background:#111!important}
      #app .portfolio-feature img{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;transition:transform .45s ease!important}
      #app .portfolio-feature::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05) 25%,rgba(0,0,0,.82) 100%)}
      #app .portfolio-feature:hover img{transform:scale(1.025)!important}
      #app .portfolio-feature-copy{position:absolute!important;z-index:2!important;left:34px!important;right:34px!important;bottom:32px!important;color:#fff!important;display:grid!important;grid-template-columns:minmax(0,1fr) auto!important;gap:20px!important;align-items:end!important}
      #app .portfolio-feature-copy small{font-size:10px!important;letter-spacing:.12em!important;text-transform:uppercase!important;color:rgba(255,255,255,.72)!important}
      #app .portfolio-feature-copy h2{margin:8px 0 8px!important;font-size:34px!important;line-height:1!important;letter-spacing:-.045em!important;color:#fff!important}
      #app .portfolio-feature-copy p{margin:0!important;max-width:620px!important;color:rgba(255,255,255,.82)!important;font-size:13px!important;line-height:1.55!important}
      #app .portfolio-open{width:48px!important;height:48px!important;border-radius:50%!important;background:#fff!important;color:#111!important;display:grid!important;place-items:center!important;font-size:22px!important;font-weight:900!important}
      #app .portfolio-grid-premium{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:18px!important;margin-top:18px!important}
      #app .portfolio-card-premium{background:#f8f8f6!important;border:1px solid #e9e9e6!important;border-radius:18px!important;overflow:hidden!important;cursor:pointer!important;transition:transform .18s ease,box-shadow .18s ease!important}
      #app .portfolio-card-premium:hover{transform:translateY(-4px)!important;box-shadow:0 16px 35px rgba(0,0,0,.07)!important}
      #app .portfolio-card-premium img{width:100%!important;aspect-ratio:1.35/1!important;object-fit:cover!important;display:block!important}
      #app .portfolio-card-body{padding:18px!important}.portfolio-card-body small{font-size:9px!important;color:#8a8a8a!important;letter-spacing:.09em!important;text-transform:uppercase!important}.portfolio-card-body h3{margin:8px 0!important;font-size:20px!important;line-height:1.08!important;letter-spacing:-.035em!important;color:#111!important}.portfolio-card-body p{margin:0!important;font-size:12px!important;line-height:1.55!important;color:#707070!important}
      #app .equipment-line{display:flex!important;gap:7px!important;flex-wrap:wrap!important;margin-top:14px!important}.equipment-chip{display:inline-flex!important;align-items:center!important;min-height:28px!important;padding:0 10px!important;border-radius:999px!important;background:#fff!important;border:1px solid #e4e4e1!important;font-size:9px!important;font-weight:800!important;color:#333!important}

      #app .article-feature{display:grid!important;grid-template-columns:1.15fr .85fr!important;background:#111!important;border-radius:24px!important;overflow:hidden!important;margin:34px 0 26px!important;cursor:pointer!important;min-height:410px!important}
      #app .article-feature-media{position:relative!important;min-height:410px!important;overflow:hidden!important}.article-feature-media img{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;transition:transform .4s ease!important}.article-feature:hover img{transform:scale(1.025)!important}
      #app .article-feature-copy{padding:42px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;color:#fff!important}.article-feature-copy small{font-size:10px!important;letter-spacing:.1em!important;text-transform:uppercase!important;color:#f8a56f!important}.article-feature-copy h2{margin:12px 0 14px!important;font-size:36px!important;line-height:1.02!important;letter-spacing:-.05em!important;color:#fff!important}.article-feature-copy p{font-size:14px!important;line-height:1.65!important;color:rgba(255,255,255,.72)!important;margin:0 0 22px!important}.article-read{display:inline-flex!important;align-items:center!important;gap:9px!important;font-size:11px!important;font-weight:850!important;color:#fff!important}
      #app .article-grid-premium{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:18px!important}.article-card-premium{border:1px solid #e8e8e8!important;border-radius:18px!important;overflow:hidden!important;background:#fff!important;cursor:pointer!important;transition:transform .18s ease,box-shadow .18s ease!important}.article-card-premium:hover{transform:translateY(-4px)!important;box-shadow:0 14px 32px rgba(0,0,0,.07)!important}.article-card-premium img{width:100%!important;aspect-ratio:1.5/1!important;object-fit:cover!important;display:block!important}.article-card-content{padding:18px!important}.article-card-content small{font-size:9px!important;color:#8a8a8a!important;letter-spacing:.07em!important;text-transform:uppercase!important}.article-card-content h3{margin:8px 0!important;font-size:19px!important;line-height:1.12!important;letter-spacing:-.03em!important;color:#111!important}.article-card-content p{margin:0!important;font-size:12px!important;line-height:1.55!important;color:#6f6f6f!important}

      #app .editorial-detail{max-width:1120px!important;padding-top:32px!important;padding-bottom:68px!important}.editorial-back{width:44px!important;height:44px!important;border-radius:50%!important;border:1px solid #e1e1e1!important;background:#fff!important;display:grid!important;place-items:center!important;cursor:pointer!important;font-size:20px!important;margin-bottom:24px!important;box-shadow:0 4px 14px rgba(0,0,0,.04)!important}.editorial-detail-meta{font-size:10px!important;letter-spacing:.1em!important;text-transform:uppercase!important;color:#858585!important}.editorial-detail h1{max-width:900px!important;margin:10px 0 18px!important;font-size:clamp(38px,5vw,68px)!important;line-height:.98!important;letter-spacing:-.055em!important;color:#111!important}.editorial-lead{max-width:760px!important;font-size:17px!important;line-height:1.65!important;color:#6a6a6a!important;margin:0 0 30px!important}.editorial-detail-image{width:100%!important;max-height:650px!important;object-fit:cover!important;border-radius:22px!important;display:block!important;margin-bottom:32px!important}.editorial-copy{display:grid!important;grid-template-columns:minmax(0,1fr) 300px!important;gap:54px!important}.editorial-copy-main p{font-size:15px!important;line-height:1.85!important;color:#3f3f3f!important;margin:0 0 18px!important}.editorial-side{border-left:1px solid #e8e8e8!important;padding-left:24px!important}.editorial-side h3{font-size:12px!important;text-transform:uppercase!important;letter-spacing:.1em!important;margin:0 0 14px!important}.editorial-side-row{padding:11px 0!important;border-bottom:1px solid #eee!important;font-size:12px!important;color:#777!important}.editorial-side-row b{display:block!important;color:#111!important;margin-top:3px!important}

      @media(max-width:900px){#app .editorial-hero{grid-template-columns:1fr!important;gap:16px!important}.portfolio-grid-premium,.article-grid-premium{grid-template-columns:repeat(2,minmax(0,1fr))!important}.article-feature{grid-template-columns:1fr!important}.article-feature-media{min-height:330px!important}.editorial-copy{grid-template-columns:1fr!important;gap:26px!important}.editorial-side{border-left:0!important;border-top:1px solid #e8e8e8!important;padding:22px 0 0!important}}
      @media(max-width:620px){
        #app .editorial-page>.container{padding-top:22px!important}.editorial-page{padding-bottom:44px!important}
        #app .editorial-hero{padding:24px 0 26px!important}.editorial-hero h1{font-size:42px!important}.editorial-hero p{font-size:12px!important;line-height:1.6!important}.editorial-stats{gap:18px!important;margin-top:16px!important}.editorial-stat b{font-size:17px!important}
        #app .portfolio-feature{min-height:390px!important;border-radius:18px!important;margin-top:24px!important}.portfolio-feature-copy{left:18px!important;right:18px!important;bottom:18px!important;grid-template-columns:1fr!important}.portfolio-feature-copy h2{font-size:25px!important}.portfolio-open{display:none!important}
        #app .portfolio-grid-premium,#app .article-grid-premium{grid-template-columns:1fr!important;gap:12px!important}.portfolio-card-premium,.article-card-premium{border-radius:15px!important}.portfolio-card-body,.article-card-content{padding:14px!important}.portfolio-card-body h3,.article-card-content h3{font-size:17px!important}
        #app .article-feature{border-radius:18px!important;margin-top:24px!important;min-height:0!important}.article-feature-media{min-height:230px!important}.article-feature-copy{padding:22px!important}.article-feature-copy h2{font-size:27px!important}.article-feature-copy p{font-size:12px!important}
        #app .editorial-detail{padding-top:20px!important}.editorial-back{width:40px!important;height:40px!important;margin-bottom:18px!important}.editorial-detail h1{font-size:38px!important}.editorial-lead{font-size:14px!important;margin-bottom:22px!important}.editorial-detail-image{border-radius:16px!important;margin-bottom:24px!important}.editorial-copy-main p{font-size:14px!important;line-height:1.75!important}
      }
    `;
    document.head.appendChild(st);
  }

  function portfolioPage(){
    const f=PORT[0], rest=PORT.slice(1);
    return `<section class="page editorial-page"><div class="container"><div class="editorial-hero"><div><div class="editorial-kicker">Production Portfolio</div><h1>Stories built with cinema gear.</h1><div class="editorial-stats"><div class="editorial-stat"><b>${PORT.length}</b><span>Selected Projects</span></div><div class="editorial-stat"><b>2026</b><span>Latest Work</span></div><div class="editorial-stat"><b>Cinema</b><span>Production Ready</span></div></div></div><p>Showcase produksi film, commercial, music video dan documentary dengan camera package, cinema lens, lighting dan monitoring profesional.</p></div><article class="portfolio-feature" onclick="go('/portfolio/${e(f.id)}')"><img src="${e(f.img)}" alt="${e(f.title)}"><div class="portfolio-feature-copy"><div><small>${e(f.year)} · ${e(f.cat)} · Featured Project</small><h2>${e(f.title)}</h2><p>${e(f.desc)}</p></div><div class="portfolio-open">↗</div></div></article><div class="portfolio-grid-premium">${rest.map(x=>`<article class="portfolio-card-premium" onclick="go('/portfolio/${e(x.id)}')"><img src="${e(x.img)}" alt="${e(x.title)}" loading="lazy"><div class="portfolio-card-body"><small>${e(x.year)} · ${e(x.cat)}</small><h3>${e(x.title)}</h3><p>${e(x.desc)}</p><div class="equipment-line"><span class="equipment-chip">${e(x.camera)}</span><span class="equipment-chip">${e(x.lenses)}</span></div></div></article>`).join('')}</div></div></section>`;
  }

  function portfolioDetail(id){
    const x=PORT.find(v=>v.id===id); if(!x) return portfolioPage();
    return `<section class="page"><div class="container editorial-detail"><button class="editorial-back" onclick="go('/portfolio')" aria-label="Kembali">←</button><div class="editorial-detail-meta">${e(x.year)} · ${e(x.cat)} · Rentcam Production Portfolio</div><h1>${e(x.title)}</h1><p class="editorial-lead">${e(x.desc)}</p><img class="editorial-detail-image" src="${e(x.img)}" alt="${e(x.title)}"><div class="editorial-copy"><div class="editorial-copy-main"><p>Project ini dibangun dengan pendekatan camera package yang menyesuaikan kebutuhan visual, mobilitas crew, workflow monitoring dan karakter lensa.</p><p>Konfigurasi equipment disusun supaya proses produksi tetap cepat, stabil dan konsisten dari persiapan sampai shooting selesai.</p></div><aside class="editorial-side"><h3>Equipment</h3><div class="editorial-side-row">Camera<b>${e(x.camera)}</b></div><div class="editorial-side-row">Lenses<b>${e(x.lenses)}</b></div><div class="editorial-side-row">Production Type<b>${e(x.cat)}</b></div><div class="editorial-side-row">Year<b>${e(x.year)}</b></div></aside></div></div></section>`;
  }

  function articlePage(){
    const f=ART[0], rest=ART.slice(1);
    return `<section class="page editorial-page"><div class="container"><div class="editorial-hero"><div><div class="editorial-kicker">Rentcam Journal</div><h1>Guides for better productions.</h1></div><p>Artikel tentang camera system, cinema lens, lighting, workflow set dan cara memilih equipment yang tepat untuk setiap jenis produksi.</p></div><article class="article-feature" onclick="go('/artikel/${e(f.id)}')"><div class="article-feature-media"><img src="${e(f.img)}" alt="${e(f.title)}"></div><div class="article-feature-copy"><small>${e(f.cat)} · ${e(f.date)}</small><h2>${e(f.title)}</h2><p>${e(f.excerpt)}</p><span class="article-read">Baca artikel <span>→</span></span></div></article><div class="article-grid-premium">${rest.map(x=>`<article class="article-card-premium" onclick="go('/artikel/${e(x.id)}')"><img src="${e(x.img)}" alt="${e(x.title)}" loading="lazy"><div class="article-card-content"><small>${e(x.cat)} · ${e(x.date)}</small><h3>${e(x.title)}</h3><p>${e(x.excerpt)}</p></div></article>`).join('')}</div></div></section>`;
  }

  function articleDetail(id){
    const x=ART.find(v=>v.id===id); if(!x) return articlePage();
    return `<section class="page"><div class="container editorial-detail"><button class="editorial-back" onclick="go('/artikel')" aria-label="Kembali">←</button><div class="editorial-detail-meta">${e(x.cat)} · ${e(x.date)} · Rentcam Journal</div><h1>${e(x.title)}</h1><p class="editorial-lead">${e(x.excerpt)}</p><img class="editorial-detail-image" src="${e(x.img)}" alt="${e(x.title)}"><div class="editorial-copy"><div class="editorial-copy-main"><p>Dalam produksi cinema, pemilihan equipment perlu mengikuti kebutuhan visual, workflow set, ukuran crew, lokasi dan kebutuhan post-production. Spesifikasi tinggi saja tidak cukup; compatibility dan reliability tetap menjadi faktor utama.</p><p>Camera body, cinema lens, media, battery, monitoring, wireless video, follow focus, grip dan lighting perlu dirancang sebagai satu sistem supaya crew dapat bekerja lebih efisien.</p><p>Rentcam membantu menyusun package berdasarkan kebutuhan produksi agar konfigurasi tetap praktis, aman dan siap digunakan di lapangan.</p></div><aside class="editorial-side"><h3>Article Info</h3><div class="editorial-side-row">Category<b>${e(x.cat)}</b></div><div class="editorial-side-row">Published<b>${e(x.date)}</b></div><div class="editorial-side-row">Topic<b>Cinema Equipment</b></div></aside></div></div></section>`;
  }

  function install(){
    if(typeof PORT==='undefined'||typeof ART==='undefined'||typeof go!=='function') return false;
    installStyle();
    window.portfolio=portfolioPage; window.portDetail=portfolioDetail; window.articles=articlePage; window.artDetail=articleDetail;
    try{ portfolio=portfolioPage; portDetail=portfolioDetail; articles=articlePage; artDetail=articleDetail; }catch(_){ }
    if(/^\/(portfolio|artikel)(\/|$)/.test(location.pathname) && typeof render==='function') render();
    return true;
  }

  let tries=0; const t=setInterval(()=>{tries++; if(install()||tries>50) clearInterval(t)},80);
})();